define(["jquery"],function($){const create=(root,config)=>{return new Promise((resolve,reject)=>{if(!config.adaptermodule){reject(new Error("Missing video source adapter module."));return}require([config.adaptermodule],provider=>{try{if(!provider||typeof provider.create!=="function"){throw new Error("Invalid video source adapter module.")}Promise.resolve(provider.create(root,config)).then(resolve).catch(reject)}catch(error){reject(error)}},reject)})};return{create:create}});